def number_existing(apps, schema_editor):
    """Each store's purchases so far, numbered 1, 2, 3, ... in the order they were opened;
    the store's counter continues from its last number."""
    Purchase = apps.get_model("purchases", "Purchase")
    Seller = apps.get_model("sellers", "Seller")
    for seller in Seller.objects.all():
        number = 0
        for purchase in Purchase.objects.filter(seller=seller).order_by("created_at", "id"):
            number += 1
            Purchase.objects.filter(pk=purchase.pk).update(store_number=number)
        Seller.objects.filter(pk=seller.pk).update(purchase_counter=number)


